CREATE TYPE "SupplierStatus" AS ENUM ('ACTIVE','PASSIVE','ARCHIVED');
CREATE TABLE "Supplier" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "legalName" TEXT, "phone" TEXT, "email" TEXT, "website" TEXT, "taxNumber" TEXT, "taxOffice" TEXT, "currency" TEXT NOT NULL DEFAULT 'TRY', "status" "SupplierStatus" NOT NULL DEFAULT 'ACTIVE', "address" JSONB, "metrixNote" TEXT, "executiveSummary" JSONB, "deliveryPerformance" JSONB, "qualityPerformance" JSONB, "pricingPerformance" JSONB, "riskProfile" JSONB, "score" INTEGER, "source" TEXT NOT NULL DEFAULT 'MANUAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierContact" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "fullName" TEXT, "title" TEXT, "phone" TEXT, "email" TEXT, "isPrimary" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierContact_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierProduct" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "productServiceId" TEXT NOT NULL, "supplierSku" TEXT, "purchasePriceCents" BIGINT, "currency" TEXT NOT NULL DEFAULT 'TRY', "notes" TEXT, CONSTRAINT "SupplierProduct_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierContract" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "reference" TEXT, "title" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "notes" TEXT, CONSTRAINT "SupplierContract_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierCustomFieldValue" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "definitionId" TEXT NOT NULL, "valueJson" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierCustomFieldValue_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Supplier" ADD CONSTRAINT "Supplier_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupplierContact" ADD CONSTRAINT "SupplierContact_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierContact_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupplierProduct" ADD CONSTRAINT "SupplierProduct_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierProduct_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierProduct_productServiceId_fkey" FOREIGN KEY ("productServiceId") REFERENCES "ProductService"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupplierContract" ADD CONSTRAINT "SupplierContract_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierContract_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupplierCustomFieldValue" ADD CONSTRAINT "SupplierCustomFieldValue_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierCustomFieldValue_supplierId_fkey" FOREIGN KEY ("supplierId") REFERENCES "Supplier"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "SupplierCustomFieldValue_definitionId_fkey" FOREIGN KEY ("definitionId") REFERENCES "CustomFieldDefinition"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX "Supplier_organizationId_status_idx" ON "Supplier"("organizationId","status"); CREATE INDEX "Supplier_organizationId_displayName_idx" ON "Supplier"("organizationId","displayName"); CREATE INDEX "Supplier_organizationId_taxNumber_idx" ON "Supplier"("organizationId","taxNumber"); CREATE INDEX "SupplierContact_organizationId_supplierId_idx" ON "SupplierContact"("organizationId","supplierId"); CREATE INDEX "SupplierContact_organizationId_supplierId_isPrimary_idx" ON "SupplierContact"("organizationId","supplierId","isPrimary"); CREATE UNIQUE INDEX "SupplierProduct_supplierId_productServiceId_key" ON "SupplierProduct"("supplierId","productServiceId"); CREATE INDEX "SupplierProduct_organizationId_supplierId_idx" ON "SupplierProduct"("organizationId","supplierId"); CREATE INDEX "SupplierContract_organizationId_supplierId_idx" ON "SupplierContract"("organizationId","supplierId"); CREATE UNIQUE INDEX "SupplierCustomFieldValue_supplierId_definitionId_key" ON "SupplierCustomFieldValue"("supplierId","definitionId"); CREATE INDEX "SupplierCustomFieldValue_organizationId_supplierId_idx" ON "SupplierCustomFieldValue"("organizationId","supplierId"); CREATE INDEX "SupplierCustomFieldValue_organizationId_definitionId_idx" ON "SupplierCustomFieldValue"("organizationId","definitionId");
